"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["35291"],{20207(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.termo_formulario.ordem_duplicada","status":422,"titulo":"Dois termos do formul\xe1rio t\xeam a mesma ordem"},"descricao":{"codigo":"uniplus.termo_formulario.ordem_duplicada","requisitos":["UNI-REQ-0086"],"oQueAconteceu":["Dois termos exigidos pelo formul\xe1rio t\xeam o mesmo valor de `ordem`. A ordem define a posi\xe7\xe3o do termo no formul\xe1rio (UNI-REQ-0086), e com ordem repetida a posi\xe7\xe3o n\xe3o ficaria definida. A mensagem \xe9 \\"Dois termos do formul\xe1rio t\xeam a mesma ordem.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `termos[i].ordem` (nos modelos de formul\xe1rio o `field` come\xe7a por `conteudo.`). A entrada aponta a segunda ocorr\xeancia e as seguintes; a primeira fica de fora. Nada \xe9 gravado. A confer\xeancia vale tamb\xe9m para o termo cujo c\xf3digo foi recusado.","Nas duas grava\xe7\xf5es a confer\xeancia da forma de cada termo (c\xf3digo e ordem) acumula com as demais recusas do pedido, sem interromper na primeira. Nos modelos de formul\xe1rio, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["D\xea a cada termo uma `ordem` distinta."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos termos do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Termo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);